import React, { memo, useEffect, useMemo, useCallback } from 'react';
import { ModalWrapper } from './styles';
import ReplayModalContent, { Props, ScreenVisitData } from './ReplayModalContent';

function WebScreenVisitReplayIntegration({
  open,
  screenVisitList: screenVisitListRaw,
  appId,
  sessionid,
  setSessionId,
  setOpen,
  pagination,
  onPaginationChange,
  isLoading = true,
  autoOpenReplay = false,
  currentScreenName,
  entryTime,
  setEntryTime,
}: Props) {

  const [autoReplay, setAutoReplay] = React.useState(false);
  const [hash, setHash] = React.useState('');
  const [persistedActiveSession, setPersistedActiveSession] = React.useState<ScreenVisitData | null>(null);

  const setEntryTimeCallback = useCallback((time: number | null) => {
    setEntryTime(time);
  }, [setEntryTime]);

  React.useEffect(() => {
    // eslint-disable-next-line no-shadow
    const { hash } = window.location
    setHash(hash)
  }, [sessionid, screenVisitListRaw, autoOpenReplay])

  useEffect(() => {
    if (hash === '#screen-visit-replay') {
      setAutoReplay(true);
    } else {
      setAutoReplay(false);
    }
  }, [hash]);

  const screenVisitList = React.useMemo(() => {
    return screenVisitListRaw.map((item) => {
      if (item.isGroupMetaRow) {
        return {
          ...item,
          groupItems: item.groupItems.map((groupItem) => ({
            ...groupItem,
            onRowClick: () => {
              setSessionId(groupItem.id);
              setEntryTime(groupItem.entryTime);
              if ( hash === '#screen-visit-replay') {
                window.location.hash = 'screen-visit';
            }
            },
            highlightActiveRow: () => groupItem.id === sessionid
          })),
        };
      }
      return item;
    });
  }, [screenVisitListRaw, setSessionId, setEntryTime, hash, sessionid]);

  // Auto open replay when autoOpenReplay is true
  useEffect(() => {
    if (autoReplay && screenVisitList.length > 0 && !isLoading) {
      const firstSession = screenVisitList[0]?.groupItems?.[0];
      if (firstSession) {
        setOpen(true);
        setSessionId(firstSession.id);
      }
    }
  }, [autoReplay, isLoading, screenVisitList, setOpen, setSessionId]);

  const flattenedList = screenVisitListRaw.flatMap(
    (item) => item.groupItems || []
  );

  const activeSession = useMemo(
    () => flattenedList?.find((el) => el.id === sessionid) || persistedActiveSession,
    [flattenedList, sessionid, persistedActiveSession]
  );

  useEffect(() => {
    const currentPageSession = flattenedList?.find((el) => el.id === sessionid);
    if (currentPageSession) {
      setPersistedActiveSession(currentPageSession);
    }
  }, [flattenedList, sessionid]);

  return <ModalWrapper
    centered
    closable={false}
    visible={open}
    maskClosable={false}
    width={1400}
    footer={null}
    destroyOnClose
  >
    <ReplayModalContent
      open={open}
      screenVisitList={screenVisitList}
      appId={appId}
      sessionid={sessionid}
      setSessionId={setSessionId}
      setOpen={setOpen}
      pagination={pagination}
      onPaginationChange={onPaginationChange}
      isLoading={isLoading}
      activeSession={activeSession}
      setOpenReplay={setAutoReplay}
      currentScreenName={currentScreenName}
      entryTime={entryTime}
      setEntryTime={setEntryTimeCallback}
    />
  </ModalWrapper>
}

export default memo(WebScreenVisitReplayIntegration);
