import React, { useEffect, useCallback, memo } from 'react'
import { useRestrictionContext } from 'components/IntegratePages/layout/context/restrictionContext'
import LockedPage from 'components/common/LockedPage'
import { useDispatch, useSelector } from 'react-redux'
import { trackPageViews } from 'redux/actions/trackingReport'
import Illustration from 'public/static/lock-features/screens-locked-illustration.png'

const HeatmapsPageLocked = () => {
	const dispatch = useDispatch()
	const { setShowPricingModal } = useRestrictionContext()
	const { urlReducer: { url } } = useSelector( state => state )
	const { selfServeFlag } = useRestrictionContext()

	const handleClickSeePricing = useCallback( () => {
		setShowPricingModal( true )
		dispatch( trackPageViews( null, {
			eventName: 'wa_see_pricing_clicked',
			track_type: 'event',
			eventProperty: {
				source: 'Screens'
			},
		} ) )
	}, [ dispatch, setShowPricingModal ] )

	const handleClickRequestPricing = useCallback( () => {
		setShowPricingModal( true )
		dispatch( trackPageViews( null, {
			eventName: 'wa_request_pricing_clicked',
			track_type: 'event',
			eventProperty: {
				source: 'Screens'
			},
		} ) )
	}, [ dispatch, setShowPricingModal ] )

	useEffect( () => {
		dispatch( trackPageViews( null, {
			eventName: 'wa_blocked_feature_pop_up_displayed',
			track_type: 'event',
			eventProperty: {
				source: 'Screens',
				self_Checkout: selfServeFlag,
			},
		} ) )
	}, [ url, dispatch, selfServeFlag ] )

	return (
		<LockedPage
			imageSrc={ Illustration.src }
			title="Heatmaps"
			subTitle="Understand your users&apos; intent"
			list={ 
				<>
					<li>Spot screens that frustrate users the most and make them quit.</li>
					<li>Find out the most and least popular areas on the screen.</li>
					<li>Identify frustrating and unintuitive elements.</li>
					<li>Watch relevant screen replays with advanced filters.</li>
					<li>Learn how long users take to click on a specific area.</li>
					<li>Compare user behavior on different devices, platforms, app versions.</li>
				</>
			}
			selfServeFlag={ selfServeFlag }
			handleClickSeePricing={ handleClickSeePricing }
			handleClickRequestPricing={ handleClickRequestPricing }
		/>
	)
}

export default memo( HeatmapsPageLocked )