/* eslint-disable @typescript-eslint/no-explicit-any */
/* eslint-disable react/no-unstable-nested-components */
import React, { memo, useCallback, useEffect } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { Popover } from 'antd';
import ScreenReplay from 'components/features/heatmaps/HeatmapDetails/HeatmapsScreen/ScreenVIsit/ScreenReplay';
import SessionDetailSideBarV2 from 'components/shared/Sessions/DetailSideBar';
import ShareSessionModal from 'components/shared/Sessions/SharedSession/ShareSessionModal';
import { DashboardTable } from 'uxcam-frontend-components';
import { formatPlayerTime } from 'Utils/DateConversion/dateConversionUtils';
import { IReduxState } from 'types/reduxStateTypes';
import { PlayCircleFilled } from '@ant-design/icons';
import { useScreenSkippedData } from 'components/features/sessions/hooks/sessionDetailHooks';
import { useSessionVideoContext, useSessionVideoControlls, useSessionTimeLine } from 'components/shared/Sessions/Context';
import { usePagination } from 'components/features/issues/components/ReactTable/usePagination';
import { ScreenReplayWrapper, ButtonRound, ColumnCellWrapper } from './styles';
import MetaRowComponent from './MetaRowComponent';
import HeaderTitle from './HeaderTitle';

export interface ScreenVisitData {
  sessionid: string;
  id: string;
  uxcamuserid: string;
  screenDuration: number;
  entryTime: number;
  city: string;
  country: string;
  screenNumber: number;
  previousScreenName: string;
  nextScreenName: string;
  sessionUploadedDateTime: string;
  rageTapCount: number;
  screenGestureCount: number;
  doubleTapCount: number;
  singleTapCount: number;
  swipeLeftCount: number;
  swipeRightCount: number;
  swipeUpCount: number;
  swipeDownCount: number;
  zoomInCount: number;
  zoomOutCount: number;
  longPressCount: number;
  deadClickCount: number;
  usersessionrun: number;
  totalscreen: number;
  duration: number;
  userProperty: {
    uxcamuserid: string;
  };
  userFirstSeenDateTime: string;
  video: boolean;
  onRowClick?: () => void;
}

export type Props = {
  screenVisitList: {
    id: string;
    isGroupMetaRow: boolean;
    groupKey: string;
    groupItems: ScreenVisitData[];
    groupHeader: {
      userName: string;
      userSessionRun: number;
    };
  }[];
  pagination?: {
    pageIndex: number;
    pageSize: number;
    totalPagination: number;
  };
  onPaginationChange?: (pageIndex: number) => void;
  isLoading?: boolean;
  appId: string;
  sessionid: string;
  open: boolean;
  setOpen: (open: boolean) => void;
  setSessionId: (sessionid: string | null) => void;
  autoOpenReplay?: boolean;
  activeSession?: ScreenVisitData | null;
  setOpenReplay?: (open: boolean) => void;
  currentScreenName: string;
  entryTime: number | null;
  setEntryTime: (entryTime: number | null) => void;
};

const ReplayModalContent = ({
  screenVisitList,
  pagination: paginationData,
  onPaginationChange,
  appId,
  sessionid,
  open,
  setOpen,
  isLoading = false,
  setSessionId,
  autoOpenReplay = false,
  activeSession,
  setOpenReplay,
  currentScreenName,
  entryTime,
  setEntryTime,
}: Props) => {
  const multiScreenSkippedData = useScreenSkippedData();
  const { 
    videoElemRef, 
    nextSessionCallbackRef, 
    prevSessionCallbackRef 
  } = useSessionVideoControlls();
  const { setUserPausedVideo } = useSessionVideoContext();
  const { pagination, setPagination } = usePagination();
  const { urlReducer } = useSelector((state) => state) as IReduxState;
  const dispatch = useDispatch();

  const flattenedList = screenVisitList.flatMap(
    (item) => item.groupItems || []
  );

  useEffect(() => {
    if (paginationData) {
      setPagination({ 
        pageIndex: paginationData.pageIndex,
        pageSize: paginationData.pageSize 
      });
    }
  }, [paginationData, setPagination]);

  // Track page changes to auto-select appropriate session for navigation
  const wasNavigatingToNextPageRef = React.useRef(false);
  const wasNavigatingToPrevPageRef = React.useRef(false);
  const lastFirstSessionIdRef = React.useRef<string | null>(null);

  // Track manual navigation to prevent sync conflicts
  const isManualNavigationRef = React.useRef(false);
  const manualNavigationTimeoutRef = React.useRef<number | null>(null);

  // Auto-select session when page changes due to navigation
  useEffect(() => {
    const currentFirstSessionId = flattenedList.length > 0 ? flattenedList[0].id : null;
    const hasDataChanged = currentFirstSessionId !== lastFirstSessionIdRef.current;
    
    // Only proceed if we have new data, finished loading, no session selected, and are expecting navigation
    if (flattenedList.length > 0 && 
        !isLoading && 
        !sessionid && 
        hasDataChanged &&
        (wasNavigatingToNextPageRef.current || wasNavigatingToPrevPageRef.current)) {
      
      if (wasNavigatingToNextPageRef.current) {
        // When navigating to next page, select first session
        const firstSession = flattenedList[0];
        setSessionId(firstSession.id);
        setEntryTime?.(firstSession.entryTime);
        wasNavigatingToNextPageRef.current = false;
      } else if (wasNavigatingToPrevPageRef.current) {
        // When navigating to previous page, select last session
        const lastSession = flattenedList[flattenedList.length - 1];
        setSessionId(lastSession.id);
        setEntryTime?.(lastSession.entryTime);
        wasNavigatingToPrevPageRef.current = false;
      }
    }
    
    // Update the tracked first session ID
    lastFirstSessionIdRef.current = currentFirstSessionId;
  }, [flattenedList, sessionid, setSessionId, isLoading, paginationData?.pageIndex, setEntryTime]);

  const handleModalClose = () => {
    setOpenReplay?.(false);
    setEntryTime?.(null);
    if (videoElemRef?.current) {
      videoElemRef.current.pause();
      videoElemRef.current = null;
    }
    if (autoOpenReplay){
      window.location.hash = 'screen-visit';
    }
    dispatch({
       type: 'CURRENT_URL',
       data: {
         ...urlReducer,
         sessionid: undefined,
       },
     });
    setUserPausedVideo(true);
    setOpen(false);
    setSessionId(null);
  };

  // Create optimized session index map for O(1) lookups
  const sessionIndexMap = React.useMemo(() => {
    const map = new Map();
    flattenedList.forEach((session, index) => {
      map.set(session.id, index);
    });
    return map;
  }, [flattenedList]);

  const CustomMetaRowComponent = React.useCallback((props: any) => {
    const hasActiveItem = props.rows?.some((row: any) => row.id === sessionid) || false;
    return (
    <MetaRowComponent 
      isExpanded={props.isExpanded}
      groupHeader={props.groupHeader}
      hasActiveItem={hasActiveItem} 
    />
  )}, [sessionid]);

  // Check if navigation is possible
  const canNavigateNext = React.useMemo(() => {
    if (!sessionid || isLoading) return false;
    const currentIndex = sessionIndexMap.get(sessionid);
    if (currentIndex === undefined) return false;
    
    // Can navigate if there's a next session on current page, or if there's a next page
    const hasNextOnPage = currentIndex < flattenedList.length - 1;
    const hasNextPage = paginationData && paginationData.pageIndex < paginationData.totalPagination;
    
    return hasNextOnPage || hasNextPage;
  }, [sessionid, sessionIndexMap, flattenedList, isLoading, paginationData]);

  const canNavigatePrev = React.useMemo(() => {
    if (!sessionid || isLoading) return false;
    const currentIndex = sessionIndexMap.get(sessionid);
    if (currentIndex === undefined) return false;
    
    // Can navigate if there's a previous session on current page, or if there's a previous page
    const hasPrevOnPage = currentIndex > 0;
    const hasPrevPage = paginationData && paginationData.pageIndex > 1;

    
    return hasPrevOnPage || hasPrevPage;
  }, [sessionid, sessionIndexMap, isLoading, paginationData]);

  // Helper function to set manual navigation flag with timeout
  const setManualNavigation = React.useCallback(() => {
    isManualNavigationRef.current = true;
    
    // Clear existing timeout
    if (manualNavigationTimeoutRef.current) {
      clearTimeout(manualNavigationTimeoutRef.current);
    }
    
    // Reset flag after 1 second to allow sync to resume
    manualNavigationTimeoutRef.current = window.setTimeout(() => {
      isManualNavigationRef.current = false;
      manualNavigationTimeoutRef.current = null;
    }, 1000);
  }, []);

  // Navigation functions for next/previous session with cross-page support
  const handleNextSession = React.useCallback(() => {
    if (!sessionid || isLoading) return;
    
    setManualNavigation();
    const currentIndex = sessionIndexMap.get(sessionid);
    if (currentIndex !== undefined && currentIndex < flattenedList.length - 1) {
      // Navigate to next session on current page
      const nextSession = flattenedList[currentIndex + 1];
      setSessionId(nextSession.id);
      setEntryTime?.(nextSession.entryTime);
    } else if (paginationData && paginationData.pageIndex < paginationData.totalPagination && onPaginationChange) {
      // Navigate to first session of next page
      const nextPageIndex = paginationData.pageIndex + 1;
      wasNavigatingToNextPageRef.current = true;
      setSessionId(null); // Clear current session to trigger auto-selection
      onPaginationChange(nextPageIndex);
    }
  }, [sessionid, sessionIndexMap, flattenedList, setSessionId, isLoading, paginationData, onPaginationChange, setManualNavigation, setEntryTime]);

  const handlePrevSession = React.useCallback(() => {
    if (!sessionid || isLoading) return;
    
    setManualNavigation();
    const currentIndex = sessionIndexMap.get(sessionid);
    if (currentIndex !== undefined && currentIndex > 0) {
      // Navigate to previous session on current page
      const prevSession = flattenedList[currentIndex - 1];
      setSessionId(prevSession.id);
      setEntryTime?.(prevSession.entryTime);
    } else if (paginationData && paginationData.pageIndex > 1 && onPaginationChange) {
      // Navigate to last session of previous page
      const prevPageIndex = paginationData.pageIndex - 1;
      wasNavigatingToPrevPageRef.current = true;
      setSessionId(null); // Clear current session to trigger auto-selection
      onPaginationChange(prevPageIndex);
    }
  }, [sessionid, sessionIndexMap, flattenedList, setSessionId, isLoading, paginationData, onPaginationChange, setManualNavigation, setEntryTime]);

  // Set navigation callbacks for video controls
  useEffect(() => {
    if (nextSessionCallbackRef) {
      nextSessionCallbackRef.current = canNavigateNext ? handleNextSession : null;
    }
    if (prevSessionCallbackRef) {
      prevSessionCallbackRef.current = canNavigatePrev ? handlePrevSession : null;
    }

    // Cleanup callbacks when component unmounts or modal closes
    return () => {
      if (nextSessionCallbackRef) {
        nextSessionCallbackRef.current = null;
      }
      if (prevSessionCallbackRef) {
        prevSessionCallbackRef.current = null;
      }
    };
  }, [handleNextSession, handlePrevSession, nextSessionCallbackRef, prevSessionCallbackRef, canNavigateNext, canNavigatePrev]);

  const getTableColumns = useCallback(
    () => [
      {
        accessor: 'id',
        accessorKey: 'id',
        enableSorting: false,
        header: 'Screen visits',
        minWidth: 300,
        cell: ({
          row,
        }: any) => {
          const { count, entryTime: rowEntryTime, duration, onRowClick, id } = row.original || {};
          const isActive = id === sessionid;
          return (
            <ColumnCellWrapper.FirstCell
              onClick={() => {
                setManualNavigation();
                onRowClick();
              }}
              className={isActive ? 'active-row' : ''}
              data-session-id={id}
              isActive={isActive}
            >
              <PlayCircleFilled />
              <p>Screen visit</p>
              {' '}
						  {count}
              <span>
                <p>
                {formatPlayerTime(rowEntryTime || 0)}/
                {formatPlayerTime(duration || 0)}
                </p>
              </span>
            </ColumnCellWrapper.FirstCell>
          );
        },
      },
    ],
    [sessionid, setManualNavigation]
  );

  const handleToggleFullScreen = () => {
    const modalElement = document.querySelector('.screens-replay-modal');
    if (modalElement) {
      modalElement.classList.toggle('fullscreen');
    }
  };
  useEffect(() => {
    if (open && activeSession && urlReducer.sessionid !== activeSession?.sessionid) {
      dispatch({
        type: 'CURRENT_URL',
        data: {
          ...urlReducer,
          sessionid: activeSession?.sessionid || null,
        },
      });
    }
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open, sessionid, dispatch]);


  const { rewind, currentScreen } = useSessionTimeLine();

  useEffect(() => {
    if (videoElemRef?.current?.readyState === 4 && entryTime !== null && entryTime !== undefined) {
        rewind(entryTime);
        
        // Add a small delay to ensure seek completes before playing
        const playTimer = setTimeout(() => {
          if (videoElemRef?.current) {
            videoElemRef.current.play().catch(() => null);
          }
        }, 100);
        
        return () => clearTimeout(playTimer);
    }
    return undefined
  }, [videoElemRef?.current?.readyState, entryTime, rewind, videoElemRef]);

  // Sync active session based on current screen in timeline
  useEffect(() => {
    if (!flattenedList.length || !currentScreen || !activeSession) return;
    
    // Skip sync during manual navigation to prevent conflicts
    if (isManualNavigationRef.current) return;

    // Only look at screen visits within the currently active session
    const activeSessionVisits = flattenedList.filter(session => 
      session.sessionid === activeSession.sessionid
    );

    // Find the screen visit that matches the current screen time
    const matchingVisit = activeSessionVisits.find(visit => 
      Math.abs(visit.entryTime - (currentScreen as any).time) < 0.1 // Allow small time difference
    );

    // Update active screen visit if we found a match and it's different from current
    if (matchingVisit && matchingVisit.id !== activeSession.id) {
      setSessionId(matchingVisit.id);
    }
  }, [currentScreen, flattenedList, activeSession, setSessionId]);

  // Auto-scroll to active row
  useEffect(() => {
    if (sessionid && open) {
      // Small delay to ensure DOM is updated
      const timer = setTimeout(() => {
        const activeRow = document.querySelector(`[data-session-id="${sessionid}"]`);
        if (activeRow) {
          activeRow.scrollIntoView({ 
            behavior: 'smooth', 
            block: 'center',
            inline: 'nearest'
          });
        }
      }, 100);
      
      return () => clearTimeout(timer);
    }
    return undefined;
  }, [sessionid, open]);

  return (
    <ScreenReplayWrapper.Container>
      <ScreenReplayWrapper.Header>
        <HeaderTitle currentScreen={ currentScreenName } nextScreen={ activeSession?.nextScreenName }/>
        <ScreenReplayWrapper.ShareSessionWrap>
          <ShareSessionModal selectedSession={false} shareMultiple={false} />
        </ScreenReplayWrapper.ShareSessionWrap>
        <Popover overlayClassName="custom-popover" content="Close" />
        <ButtonRound onClick={() => handleModalClose()}>
          <img src="/static/sessions/close.svg" alt="" />
        </ButtonRound>
      </ScreenReplayWrapper.Header>
      <ScreenReplayWrapper.SplitColumn>
        <ScreenReplayWrapper.TableSection>
          <DashboardTable
            data={screenVisitList}
            columns={getTableColumns()}
            resizeMode="onChange"
            enableGroupedRows
            groupConfig={{
              defaultCollapsed: false,
              metaRowComponent: CustomMetaRowComponent,
            }}
            stickyHeaders={['id']}
            enableSelection
            pagination={{
              ...pagination,
              totalPagination: paginationData?.totalPagination || 1,
            }}
            isLoading={isLoading}
            setPagination={setPagination}
            handleRouteUpdate={(currentPage) => {
              window.location.hash = 'screen-visit';
              if (onPaginationChange) {
                onPaginationChange(currentPage);
              }
            }}
          />
        </ScreenReplayWrapper.TableSection>
        <ScreenReplayWrapper.ReplaySection>
          <ScreenReplay
            sessionList={{
              body: flattenedList,
            }}
            appId={appId}
            sessionId={activeSession?.sessionid || ''}
            uploadedOn={activeSession?.sessionUploadedDateTime}
            multiScreenSkippedData={multiScreenSkippedData}
            userId={activeSession?.userProperty?.uxcamuserid}
            toggleFullScreen={handleToggleFullScreen}
          />
        </ScreenReplayWrapper.ReplaySection>
        <ScreenReplayWrapper.ReplaySidebar>
          <SessionDetailSideBarV2
            multiScreenSkippedData={multiScreenSkippedData}
            uploadedOn={activeSession?.sessionUploadedDateTime}
            detailErrorMessage=""
          />
        </ScreenReplayWrapper.ReplaySidebar>
      </ScreenReplayWrapper.SplitColumn>
    </ScreenReplayWrapper.Container>
  );
};

export default memo(ReplayModalContent); 