import React, { memo } from 'react';
import ChevronDown from 'public/static/icon-chevron-down.svg'
import { MetaRowWrapper } from './styles';

type MetaRowComponentProps = {
  isExpanded: boolean;
  groupHeader?: {
    userName: string;
    userSessionRun: string;
  };
  hasActiveItem?: boolean;
};

const MetaRowComponent: React.FC<MetaRowComponentProps> = ({
  isExpanded,
  groupHeader,
  hasActiveItem = false,
}) => {
  return(
  <MetaRowWrapper.MetaRowTd 
    colSpan={1} 
    isExpanded={isExpanded}
    isActive={hasActiveItem}
    data-group-header
  >
    <MetaRowWrapper.MetaRowTitle isActive={hasActiveItem}>
      {groupHeader?.userName}{' '}
      <MetaRowWrapper.MetaRowSubTitle>
        Session {groupHeader?.userSessionRun}
      </MetaRowWrapper.MetaRowSubTitle>
    </MetaRowWrapper.MetaRowTitle>
    <MetaRowWrapper.CaretIconWrapper isExpanded={isExpanded}>
      <ChevronDown />
    </MetaRowWrapper.CaretIconWrapper>
  </MetaRowWrapper.MetaRowTd>
);}

export default memo(MetaRowComponent); 