import React, { memo } from 'react'
import styled from 'styled-components';
import Arrow from 'public/static/ArrowRight.svg';
import { theme } from 'theme';

const TitleWrapper = styled.div`
    display: flex;
    align-items: center;
    gap: 10px;
    > svg path {
        fill: ${theme.colors.primaryMidnight.toString()};
    }
    span{
        color: ${theme.colors.primaryMidnight.toString()};
        font-weight: 700;
        font-size: 14px;

        &:last-of-type{
            color: ${theme.colors.surface300.toString()};
            font-weight: 500;
        }
    }
`

const HeaderTitle:React.FC<{
    currentScreen?: string;
    nextScreen?: string;
}> = ({
    currentScreen,
    nextScreen,
}) => {
  return (
    <TitleWrapper>
        { currentScreen && <span>{currentScreen}</span> }
        { nextScreen && <Arrow /> }
        { nextScreen && <span>{nextScreen}</span> }
    </TitleWrapper>
  )
}

export default memo(HeaderTitle)