import React, { memo, useCallback, useMemo } from 'react'
import ReactDOM from 'react-dom'

import { theme } from 'theme';
import { DeviceType } from '../utils';
import HeatmapTooltip from '../HeatmapTooltip';
import EmptyPlaceholder from '../EmptyPlaceholder';

interface OverlayProps {
    key: string;
    ogKey: string;
    value: number;
    box: DOMRect;
    percentage: number;
    gradientPercentage: number;
    totalClicks?: number;
    totalScreenVisits?: number;
    clickThroughRate?: number;
    depth: number;
    rank: number;
}

interface HeatmapOverlayProps {
    overlays: Array<OverlayProps>,
    iframeScale: number,
    iframeLoaded: boolean,
    deviceType: DeviceType,
    containerRef?: React.RefObject<HTMLIFrameElement>,
    tooltipContainer?: HTMLDivElement,
    opacity?: number
    rankVisible?: boolean;
}

const HeatmapOverlayPortal: React.FC<HeatmapOverlayProps> = ({ overlays, iframeScale, containerRef, iframeLoaded, deviceType, opacity = 0.3, tooltipContainer, rankVisible }) => {

    // Use a ref to track the current tooltip state to prevent race conditions
    const tooltipRef = React.useRef<{
        overlayElement: HTMLElement;
        value: number;
        percentage: number;
        isActive: boolean;
        totalClicks?: number;
        totalScreenVisits?: number;
        clickThroughRate?: number;
    } | null>(null);

    // Use state for rendering
    const [tooltip, setTooltip] = React.useState<{
        overlayElement: HTMLElement;
        value: number;
        percentage: number;
        isActive: boolean;
        totalClicks?: number;
        totalScreenVisits?: number;
        clickThroughRate?: number;
        key?: string;
        ogKey?: string;
    } | null>(null);

    // Debounce tooltip updates to prevent flickering
    const tooltipUpdateTimeout = React.useRef<ReturnType<typeof setTimeout> | null>(null);

    const updateTooltip = React.useCallback((newTooltip: {
        overlayElement: HTMLElement;
        value: number;
        percentage: number;
        isActive: boolean;
        totalClicks?: number;
        totalScreenVisits?: number;
        clickThroughRate?: number;
        key?: string;
        ogKey?: string;
    } | null) => {
        // Update ref immediately for event handlers
        tooltipRef.current = newTooltip;

        // Debounce the state update
        if (tooltipUpdateTimeout.current) {
            clearTimeout(tooltipUpdateTimeout.current);
        }

        tooltipUpdateTimeout.current = setTimeout(() => {
            setTooltip(newTooltip);
        }, 50);
    }, []);

    const closeTooltip = React.useCallback(() => {
        if (tooltipRef.current?.overlayElement) {
            tooltipRef.current.overlayElement.style.opacity = '0.3';
            tooltipRef.current.overlayElement.style.border = 'none';
        }
        updateTooltip(null);
    }, [updateTooltip]);

    // Clean up on unmount
    React.useEffect(() => {
        return () => {
            if (tooltipUpdateTimeout.current) {
                clearTimeout(tooltipUpdateTimeout.current);
            }
        };
    }, []);

    React.useEffect(() => {
        function handleClickOutside(event: MouseEvent) {
            const target = event.target as HTMLElement;
            if (
                !target.closest('.uxc-heatmap-overlay') &&
                !target.closest('[data-tooltip-container="true"]')
            ) {
                closeTooltip();
            }
        }

        document.addEventListener('click', handleClickOutside);

        // Attach to iframe document if available and loaded
        let iframeDoc: Document | null = null;
        if (iframeLoaded && containerRef?.current?.contentDocument) {
            iframeDoc = containerRef.current.contentDocument;
            iframeDoc.addEventListener('click', handleClickOutside);
        }

        return () => {
            document.removeEventListener('click', handleClickOutside);
            if (iframeDoc) {
                iframeDoc.removeEventListener('click', handleClickOutside);
            }
        };
    }, [closeTooltip, iframeLoaded, containerRef]);

    // Helper function to determine badge position
    const getBadgePosition = useCallback((box: DOMRect, badgeWidth: number, badgeMargin: number) => {
        // Check if placing badge on the left would put it outside the container
        const leftPosition = box.x - badgeMargin;
        const wouldOverflowLeft = leftPosition < 0;

        if (wouldOverflowLeft) {
            // Position on the right side of the overlay
            return {
                left: box.x + box.width + badgeMargin - badgeWidth,
                isRightPositioned: true
            };
        }
        // Default position on the left side
        return {
            left: leftPosition,
            isRightPositioned: false
        };

    }, []);

    // Render overlays in sorted order so rank 1 is always the most clicked
    const renderedOverlays = useMemo(() => overlays.map(({ key, ogKey, value, box, percentage, gradientPercentage, totalClicks, totalScreenVisits, clickThroughRate, depth, rank }) => {
        // Determine if this overlay is active (tooltip open and matches this key)
        const isActive = tooltip?.isActive && tooltip?.key === key;

        const handleClick = (event: React.MouseEvent) => {
            event.stopPropagation();

            const currentElement = event.currentTarget as HTMLElement;
            const currentTooltip = tooltipRef.current;

            // If there's any active tooltip anywhere
            if (currentTooltip?.isActive) {
                // If clicking a different overlay, close the active one and show tooltip in hover mode for the new one
                if (currentElement !== currentTooltip.overlayElement) {
                    updateTooltip({
                        key,
                        ogKey,
                        overlayElement: currentElement,
                        value,
                        percentage,
                        isActive: false, // Show as hover, not active
                        totalClicks,
                        totalScreenVisits,
                        clickThroughRate
                    });
                } else {
                    // If clicking the same active overlay, close it
                    updateTooltip(null);
                }
                return;
            }

            // Only proceed to open a new tooltip as active if there wasn't an active one
            updateTooltip({
                overlayElement: currentElement,
                value,
                percentage,
                isActive: true, // Set active on click
                totalClicks,
                totalScreenVisits,
                clickThroughRate,
                key,
                ogKey,
            });
        };

        const handleMouseEnter = (e: React.MouseEvent) => {
            const currentElement = e.currentTarget as HTMLElement;
            const currentTooltip = tooltipRef.current;
            if (!currentTooltip || !currentTooltip.isActive) {
                updateTooltip({
                    overlayElement: currentElement,
                    value,
                    percentage,
                    isActive: false,
                    totalClicks,
                    totalScreenVisits,
                    clickThroughRate,
                    key,
                    ogKey,
                });
            }
        };

        const handleMouseLeave = (e: React.MouseEvent) => {
            const currentElement = e.currentTarget as HTMLElement;
            const currentTooltip = tooltipRef.current;
            // Only hide tooltip if it's not active
            if (currentTooltip && !currentTooltip.isActive && currentTooltip.overlayElement === currentElement) {
                // Small delay before hiding to prevent flickering when moving between overlays
                setTimeout(() => {
                    // Check if the tooltip state hasn't changed during the timeout
                    if (tooltipRef.current && !tooltipRef.current.isActive &&
                        tooltipRef.current.overlayElement === currentElement) {
                        updateTooltip(null);
                    }
                }, 100);
            }
        };

        const handleKeyDown = (event: React.KeyboardEvent) => {
            if (event.key === 'Enter' || event.key === ' ') {
                handleClick(event as unknown as React.MouseEvent);
            }
        };

        // Calculate styles based on state
        const scale = 1 / iframeScale;
        let overlayOpacity = opacity;
        let overlayBorder = 'none';
        if (isActive) {
            overlayOpacity = Math.min(opacity + 0.3, 1);
            overlayBorder = `${2 * scale}px solid white`;
        } else if (tooltip && !tooltip.isActive && tooltip.key === key) {
            // Hover state
            overlayOpacity = Math.min(opacity + 0.3, 1);
            overlayBorder = `${2 * scale}px solid white`;
        }

        const overlayStyles: React.CSSProperties = {
            position: 'absolute',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            color: 'white',
            fontSize: '20px',
            fontWeight: 'bold',
            textShadow: '1px 1px 1px black',
            top: `${box.y}px`,
            left: `${box.x}px`,
            width: `${box.width}px`,
            height: `${box.height}px`,
            backgroundColor: 'rgba(255, 0, 0, 0.3)',
            zIndex: 9999 + depth,
            pointerEvents: 'auto',
            boxSizing: 'border-box',
            opacity: overlayOpacity,
            border: overlayBorder,
            background: `linear-gradient(to right, rgb(244,214,94) 0%, rgb(255,162,101) 50%, rgb(244,88,76) 100%)`,
            backgroundSize: '100000px 100000px',
            backgroundPosition: `${Math.round(gradientPercentage * 100)}% 0%`,
            backgroundRepeat: 'no-repeat',
            backgroundAttachment: 'fixed',
            cursor: 'pointer',
            transition: 'opacity 0.2s ease, border 0.2s ease', // Smooth opacity and border changes
        };

        // Position badge with smart positioning logic
        const badgeWidth = 18 / iframeScale;
        const badgeHeight = 18 / iframeScale;
        const badgeMargin = 20 / iframeScale;

        const badgePosition = getBadgePosition(box, badgeWidth, badgeMargin);

        // Determine badge visibility and styling based on tooltip state
        const isCurrentlyHovered = tooltip && tooltip.key === key;
        const shouldShowBadge = !tooltip || isCurrentlyHovered;

        const badgeStyle: React.CSSProperties = {
            position: 'absolute',
            top: box.y,
            left: badgePosition.left,
            width: badgeWidth,
            height: badgeHeight,
            background: isCurrentlyHovered ? theme.colors.primarySky.toString() : theme.colors.surface05.toString(), // Purple when hovered/active, default otherwise
            color: isCurrentlyHovered ? theme.colors.primarySnow.toString() : theme.colors.primaryMidnight.toString(), // White text when hovered/active
            fontSize: `${8 / iframeScale}px`,
            zIndex: 10001 + depth,
            boxShadow: '0 1px 4px rgba(0,0,0,0.18)',
            pointerEvents: 'none',
            userSelect: 'none',
            display: shouldShowBadge ? 'flex' : 'none',
            alignItems: 'center',
            justifyContent: 'center',
            opacity: shouldShowBadge ? 1 : 0,
            transition: 'background-color 0.2s ease, color 0.2s ease, opacity 0.2s ease',
        };

        return (
            <>
                {
                    rankVisible && (
                        <div
                            key={`rank-badge-${key}`}
                            style={badgeStyle}
                        >
                            {rank}
                        </div>
                    )
                }
                <div
                    key={key}
                    className="uxc-heatmap-overlay"
                    style={overlayStyles}
                    role="button"
                    tabIndex={0}
                    aria-label={`Heatmap overlay for ${key}`}
                    onClick={handleClick}
                    onKeyDown={handleKeyDown}
                    onMouseEnter={handleMouseEnter}
                    onMouseLeave={handleMouseLeave}
                />
            </>
        );
    }), [getBadgePosition, iframeScale, opacity, overlays, rankVisible, tooltip, updateTooltip])

    // Only create one tooltip portal
    const tooltipPortal = useMemo(() => tooltip && ReactDOM.createPortal(
        <HeatmapTooltip
            elementKey={tooltip.ogKey as string}
            overlayElement={tooltip.overlayElement}
            value={tooltip.value}
            percentage={tooltip.percentage}
            iframeScale={iframeScale}
            onClose={closeTooltip}
            isActive={tooltip.isActive}
            containerRef={containerRef}
            deviceType={deviceType}
            totalClicks={tooltip.totalClicks}
            totalScreenVisits={tooltip.totalScreenVisits}
            clickThroughRate={tooltip.clickThroughRate}
        />,
        tooltipContainer || document.body
    ), [tooltip, iframeScale, closeTooltip, containerRef, deviceType, tooltipContainer]);

    // Create empty placeholder portal when there are no overlays
    const emptyPlaceholderPortal = useMemo(() => overlays.length === 0 && tooltipContainer && ReactDOM.createPortal(
        <EmptyPlaceholder />,
        tooltipContainer
    ), [overlays.length, tooltipContainer]);

    if (!iframeLoaded) return null;

    return (
        <>
            <div
                className="uxc-heatmap-background-overlay"
                style={{
                    position: 'fixed',
                    top: 0,
                    left: 0,
                    right: 0,
                    bottom: 0,
                    backgroundColor: '#161E351A',
                    zIndex: 9998,
                    pointerEvents: 'none',
                }}
            />
            {overlays.length > 0 && renderedOverlays}
            {tooltipPortal}
            {emptyPlaceholderPortal}
        </>
    );
};

export default memo(HeatmapOverlayPortal)