/* eslint-disable @typescript-eslint/no-explicit-any */
/* eslint-disable no-console */
/* eslint-disable @typescript-eslint/no-non-null-assertion */
/* eslint-disable no-shadow */
import React from 'react'
import WebReplay from 'components/shared/Sessions/Video/WebReplay'
import { IVideoInterface } from 'components/shared/Sessions/Video/WebReplay/types'
import styled from 'styled-components'
import ReactDOMClient from 'react-dom/client';
import { debounce } from 'lodash';
import HeatmapOverlayPortal from './HeatmapOverlayPortal';
import { calculateSmartZIndex, DeviceType, escapeComplexSelector, getSize, isWrapperElement } from './utils';

const Container = styled.div`
	width: 100%;
	margin: 10px;
	position: relative;
	overflow: hidden;
`

const Inner = styled.div`
	position: absolute;
	top: 50%;
	left: 50%;
	transform: translate(-50%, -50%);
	pointer-events: none;
	iframe {
		pointer-events: initial;
	}
`

interface WebReplayIntegrationProps {
	deviceType: DeviceType;
	time: number;
	src: string;
	clickData: Record<string, number>;
	topElements: number;
	totalScreenVisits?: number;
	opacity?: number;
	rankVisible?: boolean;
}

interface HeatmapOverlay {
	key: string;
	ogKey: string;
	value: number;
	box: DOMRect;
	percentage: number;
	gradientPercentage: number;
	totalClicks: number;
	totalScreenVisits: number;
	clickThroughRate: number;
	depth: number;
	rank: number;
}

interface ProcessedElementResult {
	key: string;
	element: HTMLElement;
	iframeElement: HTMLIFrameElement | null;
	iframeChain: HTMLIFrameElement[];
	contextWindow: Window | null;
}

const WebReplayIntegration: React.FC<WebReplayIntegrationProps> = React.memo(({
	time,
	src,
	deviceType,
	clickData,
	topElements,
	totalScreenVisits = 0,
	opacity = 0.3,
	rankVisible = true
}) => {
	const iframeSize = React.useMemo(() => {
		return getSize(deviceType)
	}, [deviceType])

	const videoRef = React.useRef<IVideoInterface>()
	const containerRef = React.useRef<HTMLDivElement>()
	const [iframeLoaded, setIframeLoaded] = React.useState(false)
	const [iframeScale, setIframeScale] = React.useState(1);

	// Cache iframe and container references
	const iframeRef = React.useRef<HTMLIFrameElement | null>(null);
	const heatmapRootRef = React.useRef<any>(null);

	// Memoize processed click data to avoid recalculating on every render
	const processedClickData = React.useMemo(() => {
		const entries = Object.entries(clickData);
		const totalClicks = entries.reduce((sum, [, value]) => sum + value, 0);
		const sortedEntries = entries.sort(([, a], [, b]) => b - a);

		return {
			entries: sortedEntries,
			totalClicks,
			maxClicks: Math.max(...entries.map(([, value]) => value)),
			minClicks: Math.min(...entries.map(([, value]) => value))
		};
	}, [clickData]);

	// Optimize element processing with memoization
	const processElement = React.useCallback((key: string): ProcessedElementResult | null => {
		if (!iframeRef.current?.contentDocument) return null;

		try {
			// `>>>` marks a boundary the recorder crossed: either into an <iframe> document or into a
			// custom element's shadow root. Only iframes shift the coordinate space, so they are tracked apart.
			const selectorSegments = key.split('>>>').map(s => s.trim());

			let currentRoot: Document | ShadowRoot | null = iframeRef.current.contentDocument;
			let deepestIframeElement: HTMLIFrameElement | null = null;
			let lastBoundary: HTMLElement | null = null;
			let lastBoundaryIsIframe = false;
			const iframeChain: HTMLIFrameElement[] = [];

			for (let i = 0; i < selectorSegments.length - 1; i += 1) {
				if (!currentRoot) return null;

				const boundarySelector = selectorSegments[i]
					.split(' > ')
					.map(part => escapeComplexSelector(part))
					.join(' > ');
				const boundaryElement = currentRoot.querySelector(boundarySelector) as HTMLElement | null;
				if (!boundaryElement) return null;

				if (boundaryElement.tagName === 'IFRAME') {
					const iframeElement = boundaryElement as HTMLIFrameElement;
					if (!iframeElement.contentDocument) return null;
					iframeChain.push(iframeElement);
					deepestIframeElement = iframeElement;
					currentRoot = iframeElement.contentDocument;
					lastBoundaryIsIframe = true;
				} else if (boundaryElement.shadowRoot) {
					currentRoot = boundaryElement.shadowRoot;
					lastBoundaryIsIframe = false;
				} else {
					return null;
				}
				lastBoundary = boundaryElement;
			}

			const selectorToQuery = selectorSegments[selectorSegments.length - 1];
			if (!currentRoot) return null;

			// Only a boundary path was provided: the target is the boundary element itself
			if (!selectorToQuery) {
				if (!lastBoundary) return null;
				const boundaryKey = selectorSegments.slice(0, -1).join(' >>> ');

				if (lastBoundaryIsIframe) {
					// The iframe lives in its parent document, so it is not part of its own offset chain
					const parentIframe = iframeChain.length > 1 ? iframeChain[iframeChain.length - 2] : null;
					return {
						key: boundaryKey,
						element: lastBoundary,
						iframeElement: parentIframe,
						iframeChain: iframeChain.slice(0, -1),
						contextWindow: parentIframe?.contentWindow || iframeRef.current.contentWindow || null
					};
				}

				return {
					key: boundaryKey,
					element: lastBoundary,
					iframeElement: deepestIframeElement,
					iframeChain,
					contextWindow: deepestIframeElement?.contentWindow || iframeRef.current.contentWindow || null
				};
			}

			const parts = selectorToQuery.split(' > ');
			let newKey = parts.map(part => escapeComplexSelector(part)).join(' > ');
			let element = currentRoot.querySelector(newKey);

			// If element not found, try without state classes
			if (!element) {
				const fallbackKey = parts
					.map(part => escapeComplexSelector(part, { removeStateClasses: true }))
					.join(' > ');

				if (fallbackKey !== newKey) {
					element = currentRoot.querySelector(fallbackKey);
					if (element) {
						newKey = fallbackKey;
					}
				}
			}

			if (!element) return null;

			// Validate element is visible and has dimensions
			const rect = element.getBoundingClientRect();
			if (rect.width === 0 || rect.height === 0) return null;

			// Check if element is actually visible
			const computedStyle = element.ownerDocument.defaultView?.getComputedStyle(element) || window.getComputedStyle(element);
			if (computedStyle.display === 'none' || computedStyle.visibility === 'hidden' || computedStyle.opacity === '0') {
				return null;
			}

			return {
				// Keep the boundary path so identical tails under different hosts stay distinct
				key: [...selectorSegments.slice(0, -1), newKey].join(' >>> '),
				element: element as HTMLElement,
				iframeElement: deepestIframeElement,
				iframeChain,
				contextWindow: deepestIframeElement?.contentWindow || iframeRef.current.contentWindow || null
			};
		} catch (error) {
			return null;
		}
	}, []);

	// Batch DOM operations and reduce expensive calculations
	const calculateOverlays = React.useCallback((): HeatmapOverlay[] => {
		if (!iframeRef.current?.contentDocument) return [];

		const { entries, totalClicks, maxClicks, minClicks } = processedClickData;
		const gradientDenominator = maxClicks - minClicks;

		// Process elements in batches to avoid blocking the main thread
		const validElements: Array<[ProcessedElementResult, number, string]> = [];

		entries.forEach(([key, value]) => {
			const result = processElement(key);
			if (result) {
				const wrapperIframe = result.iframeElement || iframeRef.current;
				if (wrapperIframe && !isWrapperElement(result.element, wrapperIframe)) {
					validElements.push([result, value, key]);
				}
			}
		});

		// Take only top elements for performance
		const topValidElements = validElements.slice(0, topElements);

		// Batch calculate all overlays
		const overlays: HeatmapOverlay[] = [];
		const scrollX = iframeRef.current.contentWindow?.scrollX || 0;
		const scrollY = iframeRef.current.contentWindow?.scrollY || 0;

		// Get body boundaries for clamping
		const { body } = iframeRef.current.contentDocument;
		const bodyRect = body.getBoundingClientRect();
		const bodyWidth = Math.max(body.scrollWidth, bodyRect.width);
		const bodyHeight = Math.max(body.scrollHeight, bodyRect.height);

		for (let idx = 0; idx < topValidElements.length; idx += 1) {
			const [processed, value, ogKey] = topValidElements[idx];
			const { key, element, iframeChain } = processed;

			try {
				const box = element.getBoundingClientRect();
				let left = box.left + scrollX;
				let top = box.top + scrollY;

				// Accumulate offsets from all iframes in the chain
				if (iframeChain.length > 0) {
					const iframeOffset = iframeChain.reduce(
						(acc, iframe) => {
							const iframeRect = iframe.getBoundingClientRect();
							return {
								left: acc.left + iframeRect.left,
								top: acc.top + iframeRect.top
							};
						},
						{ left: scrollX, top: scrollY }
					);

					left = iframeOffset.left + box.left;
					top = iframeOffset.top + box.top;
				}
				let { width } = box;
				let { height } = box;

				// Clamp overlay to body boundaries
				if (left < 0) {
					width += left;
					left = 0;
				}
				if (top < 0) {
					height += top;
					top = 0;
				}
				if (left + width > bodyWidth) {
					width = bodyWidth - left;
				}
				if (top + height > bodyHeight) {
					height = bodyHeight - top;
				}

				// Skip if overlay would be too small or completely outside body
				if (width <= 0 || height <= 0) {
					// eslint-disable-next-line no-continue
					continue;
				}

				// Create new DOMRect with clamped coordinates
				const adjustedBox = new DOMRect(left, top, width, height);

				const percentage = totalClicks > 0 ? value / totalClicks : 0;
				let gradientPercentage = 1;
				if (gradientDenominator > 0) {
					gradientPercentage = (value - minClicks) / gradientDenominator;
				}
				const clickThroughRate = totalScreenVisits > 0 ? value / totalScreenVisits : 0;
				const depth = calculateSmartZIndex(element);

				overlays.push({
					key,
					ogKey,
					value,
					box: adjustedBox,
					percentage,
					gradientPercentage,
					totalClicks,
					totalScreenVisits,
					clickThroughRate,
					depth,
					rank: idx + 1
				});
			} catch (error) {
				console.warn(`Error calculating overlay for ${key}:`, error);
			}
		}

		// Sort by depth once at the end
		return overlays.sort((a, b) => b.depth - a.depth);
	}, [processedClickData, topElements, totalScreenVisits, processElement]);

	const drawHeatmap = React.useCallback(() => {
		if (!iframeLoaded || !iframeRef.current?.contentDocument) return;
		try {
			let heatmapContainer = iframeRef.current.contentDocument.querySelector('#uxc-heatmap') as HTMLElement;
			if (!heatmapContainer) {
				heatmapContainer = document.createElement('div');
				heatmapContainer.id = 'uxc-heatmap';
				Object.assign(heatmapContainer.style, {
					position: 'absolute',
					top: '0',
					left: '0',
					width: '100vw',
					height: '100vh',
					pointerEvents: 'none',
					zIndex: '9999999999'
				});
				iframeRef.current.contentDocument?.documentElement.appendChild(heatmapContainer);
			}

			const overlays = calculateOverlays();

			// Reuse React root to avoid recreation overhead
			if (!heatmapRootRef.current) {
				heatmapRootRef.current = ReactDOMClient.createRoot(heatmapContainer);
			}

			heatmapRootRef.current.render(
				<HeatmapOverlayPortal
					overlays={overlays}
					iframeScale={iframeScale}
					containerRef={{ current: iframeRef.current }}
					iframeLoaded={iframeLoaded}
					deviceType={deviceType}
					opacity={opacity}
					tooltipContainer={containerRef.current}
					rankVisible={rankVisible}
				/>
			);
		} catch (error) {
			console.error("Error drawing heatmap:", error);
		}
	}, [iframeLoaded, calculateOverlays, iframeScale, deviceType, opacity, rankVisible]);
	const debouncedDrawHeatmapRef = React.useRef<ReturnType<typeof debounce>>();
	React.useEffect(() => {
		debouncedDrawHeatmapRef.current = debounce(() => {
			drawHeatmap();
		}, 16);

		return () => {
			debouncedDrawHeatmapRef.current?.cancel();
		};
		// eslint-disable-next-line react-hooks/exhaustive-deps
	}, []);
	React.useEffect(() => {
		if (debouncedDrawHeatmapRef.current) {
			// Cancel any pending calls with old callback
			debouncedDrawHeatmapRef.current.cancel();

			// Create new debounced function with updated callback
			debouncedDrawHeatmapRef.current = debounce(() => {
				drawHeatmap();
			}, 16);
		}
	}, [drawHeatmap]);


	const stableCallback = React.useCallback(() => {
		debouncedDrawHeatmapRef.current?.();
	}, []);


	// Optimize debounced drawing with better timing
	const debouncedDrawHeatmap = React.useMemo(() => {
		const fn = debounce(() => {
			drawHeatmap();
		}, 50); // ~60fps
		return fn;
	}, [drawHeatmap]);

	// Update iframe reference when container changes
	React.useEffect(() => {
		if (containerRef.current) {
			iframeRef.current = containerRef.current.querySelector('iframe');
		}
	}, [iframeLoaded]);

	React.useEffect(() => {
		debouncedDrawHeatmap();
		return () => {
			debouncedDrawHeatmap.cancel();
		};
	}, [opacity, iframeLoaded, debouncedDrawHeatmap, topElements, iframeScale]);

	const applyNewSize = React.useCallback(() => {
		const container = containerRef.current;
		const iframe = container?.querySelector('iframe');

		if (!container || !iframe) return;

		const deviceSize = getSize(deviceType);
		const containerSize = container.getBoundingClientRect();

		if (deviceSize && containerSize) {
			const scale = Math.min(
				containerSize.width / deviceSize.width,
				containerSize.height / deviceSize.height
			);
			iframe.style.transform = `scale(${scale})`;
			setIframeScale(scale);
		}
	}, [deviceType]);

	const handleLoad = React.useCallback(() => {
		const container = containerRef.current!
		if (!container) return undefined;

		const iframe = container.querySelector('iframe');
		if (!iframe || !iframe.contentDocument || !iframe.contentDocument.body) {
			return undefined;
		}

		// Update iframe reference
		iframeRef.current = iframe;

		// Replace the existing setupIframe function with this enhanced version
		const setupIframe = (): (() => void) | undefined => {
			try {
				const doc = iframe.contentDocument;
				if (!doc) return;

				const callback = stableCallback;
				const observers: { (): void; (): void; (): void; (): void; }[] = [];

				// Create and configure resize observer
				const resizeObserver = new ResizeObserver(callback);
				resizeObserver.observe(doc.documentElement);
				resizeObserver.observe(doc.body);
				observers.push(() => resizeObserver.disconnect());

				// Enhanced mutation observer with optimized filtering
				const mutationObserver = new MutationObserver((mutations) => {
					const hasLayoutMutation = mutations.some(mutation => {
						const target = mutation.target as Element;
						// Skip uxc-heatmap mutations early
						if (target.id === 'uxc-heatmap' || target.closest('#uxc-heatmap')) {
							return false;
						}

						// Check for layout-affecting changes
						return (mutation.type === 'attributes' &&
							(mutation.attributeName === 'style' || mutation.attributeName === 'class')) ||
							(mutation.type === 'childList' &&
								(mutation.addedNodes.length > 0 || mutation.removedNodes.length > 0));
					});

					if (hasLayoutMutation) callback();
				});

				mutationObserver.observe(doc.documentElement, {
					childList: true,
					subtree: true,
					attributes: true,
					attributeFilter: ['style', 'class'],
					characterData: false
				});
				observers.push(() => mutationObserver.disconnect());

				// Font loading observer
				if (doc.fonts) {
					const fontLoadHandler = callback;
					doc.fonts.addEventListener('loadingdone', fontLoadHandler);
					doc.fonts.addEventListener('loadingerror', fontLoadHandler);
					observers.push(() => {
						doc.fonts.removeEventListener('loadingdone', fontLoadHandler);
						doc.fonts.removeEventListener('loadingerror', fontLoadHandler);
					});
				}

				// Setup scroll listeners with delegation
				const setupScrollListeners = () => {
					const debouncedScrollCallback = debounce(() => {
						callback();
					}, 10);
					const cleanupFunctions: (() => void)[] = [];

					const attachScrollListenersToDocument = (targetDoc: Document) => {

						// Document scroll - listen on both document and documentElement
						const scrollHandler = () => debouncedScrollCallback();
						targetDoc.addEventListener('scroll', scrollHandler, { passive: true, capture: true });
						targetDoc.documentElement?.addEventListener('scroll', scrollHandler, { passive: true, capture: true });
						cleanupFunctions.push(() => {
							targetDoc.removeEventListener('scroll', scrollHandler, { capture: true });
							targetDoc.documentElement?.removeEventListener('scroll', scrollHandler, { capture: true });
						});

						// Find and attach listeners to scrollable elements
						const scrollableElements = Array.from(targetDoc.querySelectorAll('*')).filter(el => {
							const style = getComputedStyle(el);
							const hasScrollableContent = el.scrollHeight > el.clientHeight || el.scrollWidth > el.clientWidth;
							const hasScrollableStyle = ['auto', 'scroll', 'visible'].some(val =>
								[style.overflow, style.overflowY, style.overflowX].includes(val)
							);
							return hasScrollableContent && hasScrollableStyle;
						});

						scrollableElements.forEach(el => {
							el.addEventListener('scroll', scrollHandler, { passive: true, capture: true });
							cleanupFunctions.push(() => el.removeEventListener('scroll', scrollHandler, { capture: true }));
						});
					};

					// Attach to main document
					attachScrollListenersToDocument(doc);

					// Attach to nested iframes
					const nestedIframes = doc.querySelectorAll('iframe');

					const attachToNestedIframe = (nestedIframe: HTMLIFrameElement) => {
						try {
							const nestedDoc = nestedIframe.contentDocument;
							if (nestedDoc && nestedDoc.readyState === 'complete') {
								attachScrollListenersToDocument(nestedDoc);

								const iframeWindow = nestedIframe.contentWindow;
								if (iframeWindow) {
									const scrollHandler = () => debouncedScrollCallback();
									iframeWindow.addEventListener('scroll', scrollHandler, { passive: true, capture: true });
									cleanupFunctions.push(() => iframeWindow.removeEventListener('scroll', scrollHandler, { capture: true }));
								}
							} else if (nestedDoc) {
								nestedIframe.addEventListener('load', () => {
									attachToNestedIframe(nestedIframe);
								}, { once: true });
							}
						} catch (e) {
							// Cross-origin iframe, skip
						}
					};

					nestedIframes.forEach((nestedIframe) => {
						attachToNestedIframe(nestedIframe as HTMLIFrameElement);
					});

					// Return cleanup function
					return () => {
						debouncedScrollCallback.cancel();
						cleanupFunctions.forEach(cleanup => cleanup());
					};
				};

				// Disable interactivity and set cursor with single query
				const disableInteractivity = () => {
					// Batch DOM operations
					const interactiveElements = doc.querySelectorAll('a, button, input');

					// Disable interactive elements
					interactiveElements.forEach(el => {
						const element = el as HTMLElement;
						element.onclick = e => e.preventDefault();
						element.setAttribute('tabindex', '-1');
						element.style.pointerEvents = 'none';
						element.style.cursor = 'default';
					});
				};

				// Optimized stylesheet loading check
				const checkStylesLoaded = () => {
					let retryCount = 0;
					const maxRetries = 50;

					const checkStyles = () => {
						if (retryCount > maxRetries) {
							// eslint-disable-next-line no-use-before-define
							finishSetup();
							return;
						}

						const links = doc.querySelectorAll('link[rel="stylesheet"]');
						const allLoaded = links.length === 0 || Array.from(links).every(link => (link as HTMLLinkElement).sheet && !(link as HTMLLinkElement).disabled);

						if (allLoaded) {
							// eslint-disable-next-line no-use-before-define
							finishSetup();
						} else {
							retryCount += 1;
							setTimeout(checkStyles, 200);
						}
					};

					checkStyles();
				};

				// Consolidated finish setup
				const finishSetup = () => {
					// Reset scroll position
					doc.documentElement.scrollTop = 0;
					doc.documentElement.scrollLeft = 0;

					// Setup interactivity and scrolling
					disableInteractivity();
					const cleanupScrollListeners = setupScrollListeners();
					observers.push(cleanupScrollListeners);


					setIframeLoaded(true);

					// Final callback after short delay
					setTimeout(callback, 200);
				};

				// Set iframe dimensions
				Object.assign(iframe.style, {
					height: `${iframeSize.height}px`,
					width: `${iframeSize.width}px`
				});

				// Apply initial size/scale
				applyNewSize();

				// Start style loading check observation
				checkStylesLoaded();

				// Return consolidated cleanup function
				() => {
					observers.forEach(cleanup => cleanup());
				};

			} catch (error) {
				console.error("Error setting up iframe:", error);
				setIframeLoaded(true);
			}
		};

		// Optimize iframe loading check
		const checkIframeLoaded = () => {
			if (iframe.contentDocument?.readyState === 'complete') {
				return setupIframe();
			}
			setTimeout(checkIframeLoaded, 100);
			return undefined;
		};

		const cleanup = checkIframeLoaded();

		// Optimize container resize handling
		let resizeTimeout: ReturnType<typeof setTimeout>;
		const onContainerResize = () => {
			if (resizeTimeout) clearTimeout(resizeTimeout);
			resizeTimeout = setTimeout(applyNewSize, 100);
		};

		const resizeObserver = new ResizeObserver(onContainerResize);
		if (container) {
			resizeObserver.observe(container);
		}

		return () => {
			if (resizeTimeout) clearTimeout(resizeTimeout);
			resizeObserver.disconnect();
			if (cleanup) cleanup();
		};
	}, [stableCallback, iframeSize.height, iframeSize.width, applyNewSize]);

	React.useEffect(() => {
		const doCheck = () => {
			if (videoRef.current) {
				videoRef.current.addEventListener('frameloaded', handleLoad);
				return;
			}
			setTimeout(doCheck, 100);
		};
		doCheck();
	}, [videoRef, handleLoad]);

	const heatmapConfig = React.useMemo(() => ({ time }), [time]);

	return (
		<Container ref={containerRef as React.MutableRefObject<HTMLDivElement>}>
			<Inner>
				<WebReplay
					key={src}
					src={src}
					autoPlay={false}
					videoRef={videoRef as React.MutableRefObject<IVideoInterface>}
					skipInactivity={false}
					heatmap={heatmapConfig}
				/>
			</Inner>
		</Container>
	);
});

export default WebReplayIntegration;