import React, { useMemo } from 'react';
import 'dashboard-builder/dist/cjs/style.css';
import DashboardBuilder from 'dashboard-builder/dist/cjs/App';
import { useDispatch, useSelector } from 'react-redux';
import { fetchPlanHatApi, sidebarCollapse } from 'redux/actions/common';
import Router, { useRouter } from 'next/router';
import { useRestrictionContext } from 'components/IntegratePages/layout/context/restrictionContext';
import { trackPageViews } from 'redux/actions/trackingReport';
import { tokenRefreshManager } from 'services/tokenRefreshManager';
import { useFeatureFlag } from 'uxcam-frontend-components';
import { useLeavePageConfirmation } from 'hooks/useLeavePageConfirmation';
import { useIsAppType } from 'hooks/useIsAppType';
import useIsLoggedInAdmin from 'hooks/useIsLoggedInAdmin';
import MassUserIdFilter from 'components/shared/GlobalFilter/components/MassUserIdFilter';
import { useNoCodeEventsContext } from '../sessions/Context/NoCodeEventsContext';
import WebReplayIntegration from '../WebHeatmap/WebReplayIntegration';
import HeatmapsPageLocked from '../heatmaps/HeatmapsPageLocked';
import WebScreenVisitReplayIntegration from '../WebHeatmap/WebScreenVisitReplayIntegration';

const env = process.env.APP_ENV || 'local';

const CustomDashboard = () => {
  const { query } = useRouter()
  const {
    appId,
    reportId,
    dashboardId,
    templateId,
    parentType,
    url
  } = query

  const {
    urlReducer: urlQuery,
    currentAppReducer: { orgId },
    profileReducer: profile,
  } = useSelector((state) => state);


  const dispatch = useDispatch();
  const restrictionContext = useRestrictionContext()
  const { alertsFeatureAllowed, retentionFeatureAllowed, screensFeatureAllowed, aiSessionFeatureAllowed: aiSessionsEnabled } = restrictionContext || {}
  const { noCodeEventsFeatureFlag } = useNoCodeEventsContext()
  const { contextHolder, handlePreventLeaving } = useLeavePageConfirmation();
  const conversionEnabled = useFeatureFlag('conversion-report')
  const isWebHeatmapsEnabled = useFeatureFlag('web-heatmaps');
  const isDashboardTemplateEnabled = useFeatureFlag( 'dashboard-template' )

  const trackEvent = React.useCallback(
    (eventName, property) => {
      dispatch(
        fetchPlanHatApi({
          action: eventName,
          property,
        })
      );
      dispatch(trackPageViews(null, {
        eventName,
        track_type: 'event',
        eventProperty: property,
        pageName: urlQuery.parentType,
      }))
    },
    [dispatch]
  );

  
  const newScreenFilter = useFeatureFlag('new-screens-filter')
  const isWebSDK = useIsAppType('web');
  const isWebHeatmaps = useMemo(() => parentType === 'webHeatmaps', [ parentType ])
  const redirectTimeoutRef = React.useRef(null);

  React.useEffect(() => {
    if (isWebHeatmaps && screensFeatureAllowed) {
      dispatch(sidebarCollapse(true))
    }
  }, [dispatch, isWebHeatmaps, screensFeatureAllowed])

  // @NOTE: Remove this with feature flag removal

  React.useEffect(() => {
    if (redirectTimeoutRef.current) {
      clearTimeout(redirectTimeoutRef.current);
    }

    if (!isWebHeatmapsEnabled && appId && isWebHeatmaps) {
      redirectTimeoutRef.current = setTimeout(() => {
        // Check again before redirecting to ensure feature is still disabled, because of LD inconsistency
        if (!isWebHeatmapsEnabled && appId) {
          Router.push(
            `/integration?parentType=overview&appId=${appId}`,
            `/app/${appId}/overview`
          )
        }
      }, 1500);
    }

    // Cleanup function to clear timeout on unmount or dependency change
    return () => {
      if (redirectTimeoutRef.current) {
        clearTimeout(redirectTimeoutRef.current);
      }
    };
  }, [ appId, isWebHeatmapsEnabled, isWebHeatmaps ])

  
  const onNavigate = React.useCallback( (
    url,
    navigateAppId,
    navigateDashboardId = undefined,
  ) => {
    let lastDashboard = null
    try {
      lastDashboard = localStorage.getItem('dashboard_builder.lastDashboard')
    } catch (err) {
      // silent fail
    }
    const queryParams = new URLSearchParams({
      appId: navigateAppId,
      dashboardId: navigateDashboardId || lastDashboard,
      parentType: 'customDashboard',
    } )
    Router.push(
        `/integration?${ queryParams.toString() }`, url,
    )
  }, [] )

  const onAlertNavigate = React.useCallback( ( isEdit ) => {
    if ( isEdit ) {
      Router.push(
        `/integration?parentType=settings&setting=app_setting&org=${orgId}&app=${urlQuery.appId}&app_tab=alerts`,
        `/settings/app/${orgId}/${urlQuery.appId}/alerts`
      )
    }
    else Router.push(
      `/integration?parentType=settings&setting=app_setting&org=${orgId}&app=${urlQuery.appId}&app_tab=alerts`,
      `/settings/app/${orgId}/${urlQuery.appId}/alerts#create-alert`
    )
  }, [ orgId, urlQuery.appId ] )

  const { appRole, orgRole } = React.useMemo(() => {
    const org = profile?.organization?.find((o) => o.$oid === orgId);
    return {
      appRole: org?.apps?.find((a) => a.id === appId)?.role,
      orgRole: org?.role,
    };
  }, [profile, orgId, appId]);

  const { isLoggedInAsAdminAdmin, isLoggedInAsAdminGuest } = useIsLoggedInAdmin();

  const isManager = isLoggedInAsAdminGuest ? false : (isLoggedInAsAdminAdmin || appRole === 'admin' || orgRole === 'manager' || orgRole === 'owner');
  const isOwner = isLoggedInAsAdminGuest ? false : (isLoggedInAsAdminAdmin || orgRole === 'owner');
  const isViewer = isLoggedInAsAdminGuest ? true : appRole === 'viewer';

  const key = React.useMemo(() => `${ appId }-${ parentType }`, [ appId, parentType ])

  const updateProgressFlag = (value) => {
    handlePreventLeaving(value);
  }

  const isManageCohorts = parentType === 'retention' && url && url.includes('retention/cohorts#manage');

  if ( parentType === 'heatmapsList' ) {
    // url is not synchronized
    return null
  }

  if ( parentType === 'webHeatmaps' && !screensFeatureAllowed ){
    return <HeatmapsPageLocked />
  }

  return (
    <div className="iframe-custom-dashboard-container">
      { contextHolder }
      <DashboardBuilder
        key={ key }
        appId={ appId }
        dashboardId={ dashboardId }
        trackEvent={trackEvent}
        env={ env }
        onNavigate={ onNavigate }
        onAlertNavigate={ onAlertNavigate }
        restrictionContextProp={ restrictionContext }
        templateId={ templateId }
        noCodeEnabled={ noCodeEventsFeatureFlag || false }
        isRetention={ parentType === 'retention' }
        isHeatmap={ parentType === 'webHeatmaps' }
        isManageCohorts={ isManageCohorts }
        reportId={ reportId }
        cohortsEnabled={ retentionFeatureAllowed }
        alertsEnabled={ alertsFeatureAllowed }
        conversionEnabled={ conversionEnabled }
        setChangesOnPage= { updateProgressFlag }
        isWebSDK={ isWebSDK }
        newScreenFilter={ newScreenFilter }
        HeatmapComponent={ WebReplayIntegration }
        HeatmapReplayComponent={ WebScreenVisitReplayIntegration }
        isNewAISessionEnabled={ aiSessionsEnabled}
        isDashboardTemplateEnabled={ isDashboardTemplateEnabled }
        onBeforeRequest={ tokenRefreshManager.refreshIfNeeded }
        MassUserIdModal={ MassUserIdFilter }
        isManager={ isManager }
        isOwner={ isOwner }
        isViewer={ isViewer }
      />
    </div>
  );
};

export default CustomDashboard;
