/* eslint-disable no-console */
import React from 'react';
import { throttle } from 'lodash';
import { theme } from 'theme';
import IconSession from 'public/static/icon-session-blue.svg';
import IconCaret from 'public/static/icon-caret.svg';
import { Tooltip } from 'antd';
import { CopyOutlined } from '@ant-design/icons';
import { CopyToClipboard } from 'react-copy-to-clipboard';
import { formatNumberWithCommas } from 'Utils/helpers/numberFormatter';
import { DeviceType } from '../utils';

const greyBadgeStyle: React.CSSProperties = {
    backgroundColor: theme.colors.surface10.toString(),
    borderRadius: '4px',
    padding: '2px 6px',
    fontSize: '12px',
    color: '#666',
    marginLeft: '4px',
    display: 'inline-block'
};
const rowStyle: React.CSSProperties = {
    marginBottom: '8px',
    lineHeight: '1.4'
};
const headerStyle: React.CSSProperties = {
    fontSize: '16px',
    fontWeight: 'bold',
    marginBottom: '12px'
};
const copyBtnStyles: React.CSSProperties = {
    cursor: 'pointer',
    background: 'none',
    border: 'none',
    padding: 0,
    display: 'flex',
    alignItems: 'center',
    color: theme.colors.primarySky.toString(),
}
const accordionStyles: React.CSSProperties = {
    marginBottom: '4px',
    fontWeight: 'bold',
    fontSize: '12px',
    display: 'flex',
    alignItems: 'center',
    gap: '4px',
    background: 'none',
    border: 'none',
    padding: 0,
    cursor: 'pointer',
    color: 'inherit',
    width: '100%',
}
const accordionOpenStyles: React.CSSProperties = {
    marginBottom: '10px',
    fontSize: '12px',
    color: theme.colors.surface300.toString(),
    wordBreak: 'break-all',
    maxWidth: '270px'
}
const clickToActionsStyles: React.CSSProperties = {
    backgroundColor: theme.colors.primary05.toString(),
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    padding: '8px',
    fontSize: '12px',
    color: theme.colors.surface300.toString(),
    borderRadius: '0 0 4px 4px'
}
const watchSessionsBtnStyles: React.CSSProperties = {
    border: `1px solid ${theme.colors.primary500.toString()}`,
    backgroundColor: 'transparent',
    cursor: 'pointer',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    gap: '6px',
    padding: '7px 12px',
    borderRadius: '6px',
    fontSize: '12px',
    color: theme.colors.primary500.toString(),
    fontWeight: '500',
    transition: 'background-color 0.2s ease-in-out',
    maxWidth: '133px'
}

const HeatmapTooltip: React.FC<{
    elementKey: string;
    overlayElement: HTMLElement;
    value: number;
    percentage: number;
    iframeScale: number;
    onClose: () => void;
    isActive: boolean;
    deviceType: DeviceType;
    containerRef?: React.RefObject<HTMLDivElement>;
    totalClicks?: number;
    totalScreenVisits?: number;
    clickThroughRate?: number;
}> = ({
    elementKey,
    overlayElement,
    value,
    percentage,
    iframeScale,
    onClose,
    isActive,
    containerRef,
    deviceType,
    totalClicks = 0,
    totalScreenVisits = 0,
    clickThroughRate = 0
}) => {
        const [position, setPosition] = React.useState<{
            x: number;
            y: number;
            placement: 'top' | 'bottom';
            caretPosition: 'left' | 'center' | 'right';
            caretOffset: number;
        }>({
            x: 0,
            y: 0,
            placement: 'bottom',
            caretPosition: 'center',
            caretOffset: 0
        });
        const tooltipRef = React.useRef<HTMLDivElement>(null);
        const [isAccordionOpen, setIsAccordionOpen] = React.useState(false);
        const [isCopied, setIsCopied] = React.useState(false);

        const handleCopy = React.useCallback(() => {
            setIsCopied(true);
            setTimeout(() => setIsCopied(false), 2000);
        }, []);

        React.useEffect(() => {
            if (!tooltipRef.current) return undefined;

            const updatePosition = () => {
                const tooltipRect = tooltipRef.current?.getBoundingClientRect();
                if (!tooltipRect) return;

                // Find the iframe that contains the overlay
                const iframe = overlayElement.ownerDocument?.defaultView?.frameElement as HTMLIFrameElement;
                if (!iframe) return;

                try {
                    const overlayRect = overlayElement.getBoundingClientRect();
                    const iframeRect = iframe.getBoundingClientRect();

                    // Safely get transform and calculate scale
                    let currentScale = iframeScale;
                    try {
                        const { transform } = window.getComputedStyle(iframe);
                        if (transform && transform !== 'none') {
                            const matrix = new DOMMatrix(transform);
                            currentScale = matrix.a;
                        }
                    } catch (err) {
                        console.warn('Error getting iframe transform:', err);
                    }

                    // Calculate position in the main document
                    const scaledOverlayLeft = overlayRect.left * currentScale;
                    const scaledOverlayTop = overlayRect.top * currentScale;
                    const scaledOverlayWidth = overlayRect.width * currentScale;
                    const scaledOverlayHeight = overlayRect.height * currentScale;

                    const elementLeft = iframeRect.left + scaledOverlayLeft;
                    const elementTop = iframeRect.top + scaledOverlayTop;
                    const elementWidth = scaledOverlayWidth;
                    const elementHeight = scaledOverlayHeight;
                    const elementCenter = elementLeft + (elementWidth / 2);
                    const elementBottom = elementTop + elementHeight;

                    // Get container bounds
                    let containerBounds = {
                        top: 0,
                        left: 0,
                        right: window.innerWidth,
                        bottom: window.innerHeight
                    };

                    if (containerRef?.current) {
                        const containerRect = containerRef.current.getBoundingClientRect();
                        containerBounds = {
                            top: containerRect.top,
                            left: containerRect.left,
                            right: containerRect.right,
                            bottom: containerRect.bottom
                        };
                    }

                    // Check visibility
                    if (!isActive && (
                        elementBottom < containerBounds.top ||
                        elementTop > containerBounds.bottom ||
                        elementLeft > containerBounds.right ||
                        elementLeft + elementWidth < containerBounds.left
                    )) {
                        onClose();
                        return;
                    }

                    // Calculate horizontal position and caret placement
                    let x = elementCenter;
                    let caretPosition: 'left' | 'center' | 'right' = 'center';
                    let caretOffset = 0;

                    // Check if tooltip would overflow container
                    const tooltipHalfWidth = tooltipRect.width / 2;
                    const leftOverflow = x - tooltipHalfWidth < containerBounds.left;
                    const rightOverflow = x + tooltipHalfWidth > containerBounds.right;

                    if (leftOverflow) {
                        // Align tooltip to left edge with padding
                        x = containerBounds.left + tooltipHalfWidth;
                        const idealCaretX = elementCenter;
                        caretOffset = idealCaretX - x;
                        caretPosition = 'left';
                    } else if (rightOverflow) {
                        // Align tooltip to right edge with padding
                        x = containerBounds.right - tooltipHalfWidth;
                        const idealCaretX = elementCenter;
                        caretOffset = idealCaretX - x;
                        caretPosition = 'right';
                    }

                    // Vertical placement
                    let placement: 'top' | 'bottom' = 'bottom';
                    let y = elementBottom + 10;

                    if (y + tooltipRect.height > containerBounds.bottom) {
                        if (elementTop - containerBounds.top > tooltipRect.height + 10) {
                            placement = 'top';
                            y = elementTop - 10;
                        } else {
                            y = Math.min(
                                containerBounds.bottom - tooltipRect.height - 5,
                                Math.max(containerBounds.top + 5, elementBottom)
                            );
                        }
                    }

                    setPosition({ x, y, placement, caretPosition, caretOffset });
                } catch (err) {
                    console.warn('Error calculating tooltip position:', err);
                }
            };

            // Initial position update - delay slightly to ensure everything is rendered
            const initTimer = setTimeout(updatePosition, 10);

            // Add event listeners to keep the tooltip correctly positioned
            const iframeWindow = overlayElement.ownerDocument?.defaultView;
            const mainWindow = window;

            // Try to find a main scrollable container (adjust selector as needed)
            let mainScrollContainer: HTMLElement | null = null;
            if (typeof document !== 'undefined') {
                mainScrollContainer = document.getElementById('main-scrollable-container') || document.getElementById('main-content-container');
            }

            // Handle scroll events in both the iframe, main window, and main scrollable container
            const handleScroll = () => {
                // First check if the element is still in view
                const isElementInView = () => {
                    try {
                        // Find the iframe
                        const iframe = overlayElement.ownerDocument?.defaultView?.frameElement as HTMLIFrameElement;
                        if (!iframe) return false;

                        const overlayRect = overlayElement.getBoundingClientRect();
                        const iframeRect = iframe.getBoundingClientRect();

                        // Calculate position in the main document
                        const elementLeft = iframeRect.left + (overlayRect.left * iframeScale);
                        const elementRight = elementLeft + (overlayRect.width * iframeScale);
                        const elementTop = iframeRect.top + (overlayRect.top * iframeScale);
                        const elementBottom = elementTop + (overlayRect.height * iframeScale);

                        // Get container bounds
                        let containerBounds = {
                            top: 0,
                            left: 0,
                            right: window.innerWidth,
                            bottom: window.innerHeight
                        };

                        if (containerRef?.current) {
                            const containerRect = containerRef.current.getBoundingClientRect();
                            containerBounds = {
                                top: containerRect.top,
                                left: containerRect.left,
                                right: containerRect.right,
                                bottom: containerRect.bottom
                            };
                        }

                        // Check if element is out of container bounds
                        return !(
                            elementBottom < containerBounds.top ||
                            elementTop > containerBounds.bottom ||
                            elementRight < containerBounds.left ||
                            elementLeft > containerBounds.right
                        );
                    } catch (err) {
                        console.warn('Error checking element visibility:', err);
                        return false; // Assume not in view if error
                    }
                };

                // Update position first
                updatePosition();

                // Then check if element is still in view - close tooltip if not
                if (!isElementInView()) {
                    onClose(); // Close even if active
                }
            };

            iframeWindow?.addEventListener('scroll', handleScroll);
            mainWindow.addEventListener('scroll', handleScroll);
            if (mainScrollContainer) {
                mainScrollContainer.addEventListener('scroll', handleScroll);
            }

            // Handle resize events with throttling
            const throttledResize = throttle(updatePosition, 100);
            mainWindow.addEventListener('resize', throttledResize);

            // Use resize observer
            let resizeObserver: ResizeObserver | null = null;
            try {
                resizeObserver = new ResizeObserver(throttle(() => {
                    updatePosition();
                }, 100));

                resizeObserver.observe(overlayElement);

                // Also observe container if available
                if (containerRef?.current) {
                    resizeObserver.observe(containerRef.current);
                }

                // Also observe the iframe for transform changes
                const iframe = overlayElement.ownerDocument?.defaultView?.frameElement as HTMLIFrameElement;
                if (iframe) {
                    resizeObserver.observe(iframe);
                }
            } catch (err) {
                console.warn('Error setting up ResizeObserver:', err);
            }

            // Clean up event listeners
            return function cleanup() {
                clearTimeout(initTimer);
                iframeWindow?.removeEventListener('scroll', handleScroll);
                mainWindow.removeEventListener('scroll', handleScroll);
                if (mainScrollContainer) {
                    mainScrollContainer.removeEventListener('scroll', handleScroll);
                }
                mainWindow.removeEventListener('resize', throttledResize);

                if (resizeObserver) {
                    resizeObserver.disconnect();
                }
            };
        }, [overlayElement, iframeScale, onClose, isActive, containerRef, deviceType]);

        // Update the styled component to account for active state
        const tooltipStyles: React.CSSProperties = {
            position: 'fixed',
            top: position.x === 0 && position.y === 0 ? '-9999px' : `${position.y}px`,
            left: position.x === 0 && position.y === 0 ? '-9999px' : `${position.x}px`,
            backgroundColor: 'white',
            color: '#333',
            borderRadius: '4px',
            fontSize: '14px',
            zIndex: 10000,
            transform: position.placement === 'top' ? 'translate(-50%, -100%)' : 'translate(-50%, 0)',
            pointerEvents: isActive ? 'auto' : 'none',
            transition: 'opacity 0.2s ease-in-out',
            opacity: 1,
            marginTop: position.placement === 'bottom' ? '8px' : '0',
            marginBottom: position.placement === 'top' ? '8px' : '0',
            boxShadow: '0 2px 8px rgba(0, 0, 0, 0.15)',
            minWidth: '240px'
        };

        const caretStyles: React.CSSProperties = {
            position: 'absolute',
            left: position.caretPosition === 'center' ? '50%' : 'unset',
            transform: position.caretPosition === 'center' ? 'translateX(-50%)' : 'none',
            width: '0',
            height: '0',
            borderLeft: '8px solid transparent',
            borderRight: '8px solid transparent',
            ...(position.caretPosition === 'left' && {
                left: `calc(50% + ${position.caretOffset}px)`,
            }),
            ...(position.caretPosition === 'right' && {
                left: `calc(50% + ${position.caretOffset}px)`,
            }),
            ...(position.placement === 'top' ? {
                bottom: '-8px',
                borderTop: '8px solid white',
            } : {
                top: '-8px',
                borderBottom: '8px solid white',
            })
        };

        const handleWatchSessions = React.useCallback(() => {
            try {
                sessionStorage.setItem('elementKey', elementKey);
            } catch (err) {
                // silent fail
            }
            window.location.hash = '#screen-visit-replay';
            onClose();
        }, [elementKey, onClose])

        return (
            <div ref={tooltipRef} style={tooltipStyles} data-tooltip-container="true">
                <div style={caretStyles} />
                <div style={{
                    padding: '16px',
                }}>
                    <div style={headerStyle}>
                        {formatNumberWithCommas(value)} Clicks
                    </div>

                    <div style={rowStyle}>
                        {(percentage * 100).toFixed(1)}% Click rate
                        <span style={greyBadgeStyle}>
                            out of {formatNumberWithCommas(totalClicks)} clicks
                        </span>
                    </div>

                    <div style={rowStyle}>
                        {(clickThroughRate * 100).toFixed(1)}% Click-through rate
                        <span style={greyBadgeStyle}>
                            out of {formatNumberWithCommas(totalScreenVisits)} screen visits
                        </span>
                    </div>
                </div>


                {isActive ? (
                    <div
                        style={{
                            display: 'inline-flex',
                            flexDirection: 'column',
                            padding: '0 16px 16px',
                        }}
                    >
                        <button
                            type="button"
                            onClick={() => setIsAccordionOpen(prev => !prev)}
                            style={accordionStyles}
                        >
                            <span>Element details</span>
                            <div style={{
                                transform: isAccordionOpen ? 'rotate(-180deg)' : 'rotate(0deg)',
                                transition: 'transform 0.2s ease-in-out',
                                height: '10px',
                            }}>
                                <IconCaret />
                            </div>
                            {
                                isAccordionOpen && (
                                    <Tooltip title={isCopied ? 'Copied!' : 'Copy element key'}>
                                        <button
                                            type="button"
                                            onClick={(e) => e.stopPropagation()}
                                            aria-label='Copy element key'
                                            style={copyBtnStyles}
                                        >
                                            <CopyToClipboard text={elementKey} onCopy={handleCopy}>
                                                <CopyOutlined />
                                            </CopyToClipboard>
                                        </button>
                                    </Tooltip>
                                )
                            }
                        </button>
                        {isAccordionOpen && (
                            elementKey.length > 600 ? (
                                <Tooltip title={elementKey} placement="top">
                                    <div style={accordionOpenStyles}>
                                        {elementKey.slice(0, 600)}...
                                    </div>
                                </Tooltip>
                            ) : (
                                <div style={accordionOpenStyles}>
                                    {elementKey}
                                </div>
                            )
                        )}
                        <button onClick={handleWatchSessions} type='button' className='web-heatmap-tt-btn' style={watchSessionsBtnStyles}>
                            <IconSession />
                            Watch sessions
                        </button>
                    </div>
                ) : (
                    <div style={clickToActionsStyles}>
                        Click to see actions
                    </div>
                )}
            </div>
        );
    };

export default HeatmapTooltip;