export type DeviceType = 'DESKTOP' | 'PHONE' | 'TABLET'


interface ElementMetrics {
    area: number;
    isPositioned: boolean;
    hasHigherSpecificity: boolean;
}

export const getSize = (deviceType: DeviceType) => {
    switch (deviceType) {
        case 'DESKTOP':
            return {
                width: 1920,
                height: 1080,
            }
        case 'PHONE':
            return {
                width: 375,
                height: 667,
            }
        case 'TABLET':
            return {
                width: 768,
                height: 1024,
            }
        default: {
            return {
                width: 1920,
                height: 1080,
            }
        }
    }
}

export const escapeComplexSelector = (selector: string, options: { removeStateClasses?: boolean } = {}) => {
    if (!selector) {
        return "";
    }

    // Define common transient state classes that should be filtered out
    const stateClasses = [
        'active', 'inactive',
        'hover', 'hovered', 'hovering',
        'focus', 'focused', 'focusing',
        'selected', 'unselected',
        'pressed', 'unpressed',
        'touched', 'untouched',
        'visited', 'unvisited',
        'checked', 'unchecked',
        'disabled', 'enabled',
        'loading', 'loaded',
        'open', 'closed',
        'expanded', 'collapsed',
        'visible', 'hidden',
        'current', 'past', 'future',
        'sticky',
    ];

    // Create patterns for state classes (including prefixed versions like item-active, btn-hover, etc.)
    const stateClassPatterns = stateClasses.flatMap(state => [
        state,
        `.*-${state}`, // matches any prefix followed by dash and state
        `${state}-.*`, // matches state followed by dash and any suffix
    ]);

    const createStateRegex = () => {
        const pattern = stateClassPatterns.join('|');
        return new RegExp(`^(${pattern})$`, 'i');
    };

    const isStateClass = options.removeStateClasses ?
        (className: string) => createStateRegex().test(className) :
        () => false;

    // check for id, e.g: #root
    if (selector.startsWith("#")) {
        return `#${CSS.escape(selector.slice(1))}`;
    }

    let base = selector;
    // nth-child should be last part of the selector
    const hasNthChild = selector.indexOf(":nth-child") > -1;
    if (hasNthChild) {
        // remove nth-child part from selector
        base = base.slice(0, base.indexOf(":nth-child"));
    }
    const nthChildPart = hasNthChild ? selector.slice(selector.indexOf(":nth-child")) : "";

    // check for classes
    const [elementType, ...classes] = base.split(".");

    const escapedElementType = elementType ? CSS.escape(elementType) : "";

    // Filter out state classes if requested
    const filteredClasses = options.removeStateClasses ?
        classes.filter(className => !isStateClass(className)) :
        classes;

    const escapedClasses = filteredClasses.map((className) => {
        return `.${CSS.escape(className)}`;
    });

    return `${escapedElementType}${escapedClasses.join("")}${nthChildPart}`;
};

// nodeType check instead of instanceof: replay nodes belong to the iframe's realm
const isShadowRoot = (node: Node): node is ShadowRoot =>
    node.nodeType === Node.DOCUMENT_FRAGMENT_NODE && 'host' in node;

export const calculateDOMDepth = (element: Element): number => {
    let depth = 0;
    let currentElement: Element | null = element;

    while (currentElement && currentElement !== document.documentElement) {
        depth += 1;
        const parent: Node | null = currentElement.parentNode;
        if (parent && isShadowRoot(parent)) {
            currentElement = parent.host;
        } else if (parent && parent.nodeType === Node.ELEMENT_NODE) {
            currentElement = parent as Element;
        } else {
            currentElement = null;
        }
    }

    return depth;
};


const getElementMetrics = (element: Element): ElementMetrics => {
    const rect = element.getBoundingClientRect();
    const computedStyle = window.getComputedStyle(element);

    return {
        area: rect.width * rect.height,
        isPositioned: ['absolute', 'fixed', 'relative', 'sticky'].includes(computedStyle.position),
        hasHigherSpecificity: element.matches('.nav-button, .modal, .dropdown, .tooltip, [data-priority="high"]')
    };
};

export const calculateSmartZIndex = (element: Element): number => {
    const baseDepth = calculateDOMDepth(element);
    const metrics = getElementMetrics(element);

    // Define area range and z-index range
    const minArea = 100;      // adjust as needed
    const maxArea = 10000;    // adjust as needed
    const minZ = 1000;
    const maxZ = 2000;

    // Clamp area to the expected range
    const clampedArea = Math.max(minArea, Math.min(metrics.area, maxArea));

    // Inverse linear mapping: smaller area → higher z-index
    const zIndex = Math.round(
        maxZ - ((clampedArea - minArea) / (maxArea - minArea)) * (maxZ - minZ)
    );

    // Optionally, add baseDepth if you want DOM depth to still play a role
    return zIndex + baseDepth;
};

export const isWrapperElement = (element: HTMLElement, iframe: HTMLIFrameElement): boolean => {
    // Get the iframe's content dimensions
    const iframeWidth = iframe.contentDocument?.documentElement.scrollWidth || 0;
    const iframeHeight = iframe.contentDocument?.documentElement.scrollHeight || 0;

    // Get the element's dimensions
    const rect = element.getBoundingClientRect();
    const elementWidth = rect.width;
    const elementHeight = rect.height;

    // If the element's dimensions are close to the iframe's dimensions (within 95%),
    // or if it takes up more than 90% of both width and height, consider it a wrapper
    const widthRatio = elementWidth / iframeWidth;
    const heightRatio = elementHeight / iframeHeight;

    return (widthRatio > 0.95 && heightRatio > 0.95) || (widthRatio > 0.9 && heightRatio > 0.9);
};